mapper.sql:
WHERE 1 = 1
AND A.ORG_ID = #{orgId}
AND ( LOWER(A.DEPT_ID) LIKE '%' || LOWER(#{searchValue}) || '%' OR LOWER(A.DEPTNM) LIKE '%' || LOWER(#{searchValue}) || '%' OR LOWER(A.DEPT_ENNM) LIKE '%' || LOWER(#{searchValue}) || '%' )

mapper.select:
/* SQL ID : UserMgrDeptDAO.listUserMgrDept 설 명 : 학과/부서 목록 조회 (totalCnt 포함 단일 쿼리) */
SELECT ROW_NUMBER() OVER (ORDER BY A.REG_DTTM DESC, A.DEPT_ID) AS LINE_NO , COUNT(*) OVER () AS TOTAL_CNT , A.ORG_ID , ORG.ORGNM , A.DEPT_ID , A.UP_DEPT_ID , UP.DEPTNM AS UP_DEPTNM , A.DEPTNM , A.DEPT_ENNM , A.REG_DTTM
ORDER BY A.REG_DTTM DESC, A.DEPT_ID

mapper.insert:
/*
    SQL ID : UserMgrDeptDAO.insertUserMgrDept
    설  명 : 학과/부서 등록
*/
INSERT INTO TB_LMS_DEPT (
      DEPT_ID
    , ORG_ID
    , UP_DEPT_ID
    , DEPTNM
    , DEPT_ENNM
    , RGTR_ID
    , REG_DTTM
    , MDFR_ID
    , MOD_DTTM
) VALUES (
      #{deptId}
    , #{orgId}
    , #{upDeptId}
    , #{deptnm}
    , #{deptEnnm}
    , #{rgtrId}
    , FN_DTTM()
    , #{mdfrId}
    , FN_DTTM()
)

mapper.update:
/*
    SQL ID : UserMgrDeptDAO.updateUserMgrDept
    설  명 : 학과/부서 수정
*/
UPDATE TB_LMS_DEPT
   SET DEPT_ID = #{deptId}
     , UP_DEPT_ID = #{upDeptId}
     , DEPTNM = #{deptnm}
     , DEPT_ENNM = #{deptEnnm}
     , MDFR_ID = #{mdfrId}
     , MOD_DTTM = FN_DTTM()
 WHERE DEPT_ID = #{orgDeptId}

mapper.delete:
/*
    SQL ID : UserMgrDeptDAO.deleteUserMgrDept
    설  명 : 학과/부서 삭제
*/
DELETE FROM TB_LMS_DEPT
 WHERE DEPT_ID = #{deptId}

   AND ORG_ID = #{orgId}
